// Image loading utility for optimized image loading
class ImageLoader {
  constructor() {
    this.loadedImages = new Set();
    this.failedImages = new Set();
    this.loadingPromises = new Map();
    this.criticalImages = new Set();
  }

  // Preload critical images
  preloadCriticalImages(imageUrls) {
    const promises = imageUrls.map(url => this.loadImage(url, true));
    return Promise.all(promises);
  }

  // Load image with loading state
  async loadImage(url, isCritical = false) {
    if (this.loadedImages.has(url)) {
      return { url, status: 'loaded', cached: true };
    }

    if (this.failedImages.has(url)) {
      return { url, status: 'failed', cached: false };
    }

    if (this.loadingPromises.has(url)) {
      return this.loadingPromises.get(url);
    }

    const promise = new Promise((resolve) => {
      const img = new Image();

      img.onload = () => {
        this.loadedImages.add(url);
        this.loadingPromises.delete(url);
        resolve({ url, status: 'loaded', cached: false });
      };

      img.onerror = () => {
        this.failedImages.add(url);
        this.loadingPromises.delete(url);
        resolve({ url, status: 'failed', cached: false });
      };

      img.src = url;
    });

    this.loadingPromises.set(url, promise);
    return promise;
  }

  // Load multiple images with priority
  async loadImagesWithPriority(imageUrls, priorityOrder = []) {
    const results = [];

    // Load critical images first
    for (const url of priorityOrder) {
      if (imageUrls.includes(url)) {
        const result = await this.loadImage(url, true);
        results.push(result);
      }
    }

    // Load remaining images
    const remainingUrls = imageUrls.filter(url => !priorityOrder.includes(url));
    const remainingPromises = remainingUrls.map(url => this.loadImage(url));
    const remainingResults = await Promise.all(remainingPromises);

    return [...results, ...remainingResults];
  }

  // Check if all critical images are loaded
  areCriticalImagesLoaded(criticalUrls) {
    return criticalUrls.every(url => this.loadedImages.has(url));
  }

  // Get loading progress
  getLoadingProgress(totalImages) {
    return (this.loadedImages.size / totalImages) * 100;
  }

  // Clear cache
  clearCache() {
    this.loadedImages.clear();
    this.failedImages.clear();
    this.loadingPromises.clear();
  }
}

export default new ImageLoader();
